static void ixg_mutant_count(ixg_mutant_registry_t* r, const ixg_mutant_profile_t* p) {
    if (!r || !p) return;
    if (r->total_seen != 0xFFFFFFFFu) r->total_seen++;
    if (p->vendor_id == 0x10DEu && r->nvidia_seen != 0xFFFFFFFFu) r->nvidia_seen++;
    else if ((p->vendor_id == 0x1002u || p->vendor_id == 0x1022u) && r->amd_seen != 0xFFFFFFFFu) r->amd_seen++;
    if ((p->flags & IXG_MUTANT_FLAG_MINING) && r->mining_seen != 0xFFFFFFFFu) r->mining_seen++;
    if ((p->flags & IXG_MUTANT_FLAG_DATACENTER) && r->datacenter_seen != 0xFFFFFFFFu) r->datacenter_seen++;
    if (p->headless && r->headless_seen != 0xFFFFFFFFu) r->headless_seen++;
}

int ixg_mutant_query(ix_u32 vendor_id, ix_u32 device_id, ixg_mutant_profile_t* out_profile) {
    ix_u16 vendor = (ix_u16)vendor_id;
    ix_u16 device = (ix_u16)device_id;
    ix_u32 i;
    for (i = 0u; i < sizeof(g_ixg_nvidia_mutant_exact) / sizeof(g_ixg_nvidia_mutant_exact[0]); i++) {
        if (g_ixg_nvidia_mutant_exact[i].vendor_id == vendor && g_ixg_nvidia_mutant_exact[i].device_id == device) {
            if (out_profile) *out_profile = g_ixg_nvidia_mutant_exact[i];
            return 1;
        }
    }
    for (i = 0u; i < sizeof(g_ixg_mutant_ranges) / sizeof(g_ixg_mutant_ranges[0]); i++) {
        const ixg_mutant_range_t* r = &g_ixg_mutant_ranges[i];
        if (r->vendor_id == vendor && device >= r->first && device <= r->last) {
            if (out_profile) {
                out_profile->vendor_id = vendor;
                out_profile->device_id = device;
                out_profile->family = r->family;
                out_profile->flags = r->flags;
                out_profile->class_id = r->class_id;
                out_profile->headless = r->headless;
                out_profile->vram_mb = r->vram_mb;
                out_profile->name = r->name;
            }
            return 1;
        }
    }
    return 0;
}

ix_u32 ixg_mutant_estimate_vram_mb(ix_u32 vendor_id, ix_u32 device_id, ix_u8 headless) {
    ixg_mutant_profile_t p;
    if (ixg_mutant_query(vendor_id, device_id, &p) && p.vram_mb) return p.vram_mb;
    if (vendor_id == 0x10DEu) {
        if (device_id >= 0x2900u) return 196608u;
        if (device_id >= 0x2320u) return 81920u;
        if (device_id >= 0x20B0u) return 40960u;
        if (device_id >= 0x1DB0u) return 16384u;
        return headless ? 8192u : 6144u;
    }
    if (vendor_id == 0x1002u || vendor_id == 0x1022u) {
        if (device_id >= 0x74A0u && device_id <= 0x74BFu) return 192000u;
        if (device_id >= 0x7400u && device_id <= 0x741Fu) return 131072u;
        if (device_id >= 0x7380u && device_id <= 0x739Fu) return 65536u;
        if (device_id >= 0x7300u) return headless ? 16384u : 12288u;
        if (device_id >= 0x6600u) return headless ? 8192u : 4096u;
        return headless ? 4096u : 512u;
    }
    if (vendor_id == 0x8086u) {
        if (device_id >= 0x7D00u || (device_id >= 0x5600u && device_id <= 0x56FFu)) return headless ? 8192u : 4096u;
        if (device_id >= 0x0100u) return headless ? 4096u : 2048u;
        return 64u;
    }
    return headless ? 8192u : 4096u;
}

void ixg_mutant_registry_reset(void) {
    memset(&g_ixg_mutant_registry, 0, sizeof(g_ixg_mutant_registry));
}

void ixg_mutant_registry_get(ixg_mutant_registry_t* out_registry) {
    if (out_registry) *out_registry = g_ixg_mutant_registry;
}

void ixg_mutant_init(ix_u32 vendor_id, ix_u32 device_id) {
    ixg_mutant_profile_t p;
    if (!ixg_mutant_query(vendor_id, device_id, &p)) return;
    ixg_mutant_count(&g_ixg_mutant_registry, &p);
}